import pty, os, sys, select
def run(args, env=None):
    pid, fd = pty.fork()
    if pid == 0:
        if env: os.environ.update(env)
        os.execv(args[0], args)
    out = b''
    while True:
        try:
            r, _, _ = select.select([fd], [], [], 5)
            if not r: break
            data = os.read(fd, 65536)
            if not data: break
            out += data
        except OSError:
            break
    os.waitpid(pid, 0)
    return out
out = run(['/workspace/executable', '--config-path', '/tmp/t/c.toml', '-p', '/tmp/t/a.toml'])
