/// A text style: optional foreground / background colors plus attributes.
///
/// Field order defines the derived `Ord`, which is used to sort keyword groups.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default, Deserialize)]
pub struct Style {
    #[serde(default)]
    pub fg: Option<Color>,
    #[serde(default)]
    pub bg: Option<Color>,
    #[serde(default)]
    pub bold: bool,
    #[serde(default)]
    pub faint: bool,
    #[serde(default)]
    pub italic: bool,
    #[serde(default)]
    pub underline: bool,
}

impl Style {
    pub const fn new() -> Self {
        Style {
            fg: None,
            bg: None,
            bold: false,
            faint: false,
            italic: false,
            underline: false,
        }
    }

    pub const fn fg(mut self, color: Color) -> Self {
        self.fg = Some(color);
        self
    }

    pub const fn bg(mut self, color: Color) -> Self {
        self.bg = Some(color);
        self
    }

    pub const fn bold(mut self) -> Self {
        self.bold = true;
        self
    }

    pub const fn faint(mut self) -> Self {
        self.faint = true;
        self
    }

    pub const fn italic(mut self) -> Self {
        self.italic = true;
        self
    }

    pub const fn underline(mut self) -> Self {
        self.underline = true;
        self
    }

    /// Returns the SGR parameter list (without the surrounding `ESC[` / `m`),
    /// or an empty string if the style does not set anything.
    fn sgr_params(&self) -> String {
        let mut codes: Vec<String> = Vec::new();
        if self.bold {
            codes.push("1".to_string());
        }
        if self.faint {
            codes.push("2".to_string());
        }
        if self.italic {
            codes.push("3".to_string());
        }
        if self.underline {
            codes.push("4".to_string());
        }
        if let Some(bg) = self.bg {
            codes.push(bg.bg_code().to_string());
        }
        if let Some(fg) = self.fg {
            codes.push(fg.fg_code().to_string());
        }
        codes.join(";")
    }

    /// Wraps `text` in the escape sequences for this style. A style that sets
    /// nothing returns the text unchanged.
    pub fn paint(&self, text: &str) -> String {
        let params = self.sgr_params();
        if params.is_empty() {
            return text.to_string();
        }
        let mut out = String::with_capacity(text.len() + params.len() + 7);
        out.push_str("\x1b[");
        out.push_str(&params);
        out.push('m');
        out.push_str(text);
        out.push_str("\x1b[0m");
        out
    }

    /// Appends the styled text to `out`.
    pub fn paint_into(&self, out: &mut String, text: &str) {
        let params = self.sgr_params();
        if params.is_empty() {
            out.push_str(text);
            return;
        }
        out.push_str("\x1b[");
        out.push_str(&params);
        out.push('m');
        out.push_str(text);
        out.push_str("\x1b[0m");
    }
}
