    pub separator: Style,
}

#[derive(Debug, Clone)]
pub struct UuidTheme {
    pub number: Style,
    pub letter: Style,
    pub dash: Style,
}

#[derive(Debug, Clone)]
pub struct IpTheme {
    pub number: Style,
    pub letter: Style,
    pub separator: Style,
}

#[derive(Debug, Clone)]
pub struct ProcessTheme {
