    pub comma: Style,
    pub colon: Style,
}

#[derive(Debug, Clone)]
pub struct RegexTheme {
    pub regex: String,
    pub style: Style,
}

/// Fully resolved theme (defaults merged with the user configuration).
#[derive(Debug, Clone)]
pub struct Theme {
    pub numbers: NumberTheme,
    pub urls: UrlTheme,
    pub pointers: PointerTheme,
    pub dates: DateTheme,
    pub paths: PathTheme,
    pub quotes: QuotesTheme,
    pub key_value_pairs: KeyValueTheme,
    pub uuids: UuidTheme,
    pub ip_addresses: IpTheme,
    pub processes: ProcessTheme,
    pub json: JsonTheme,
    /// Keyword groups from the configuration file (in file order).
    pub keywords: Vec<(Style, Vec<String>)>,
    /// Custom regex highlighters from the configuration file (in file order).
    pub regexes: Vec<RegexTheme>,
}

const fn s() -> Style {
    Style::new()
}

impl Theme {
    pub fn from_toml(toml: TomlTheme) -> Theme {
        let numbers = toml.numbers.unwrap_or_default();
        let urls = toml.urls.unwrap_or_default();
        let pointers = toml.pointers.unwrap_or_default();
        let dates = toml.dates.unwrap_or_default();
        let paths = toml.paths.unwrap_or_default();
        let quotes = toml.quotes.unwrap_or_default();
        let kv = toml.key_value_pairs.unwrap_or_default();
        let uuids = toml.uuids.unwrap_or_default();
        let ips = toml.ip_addresses.unwrap_or_default();
        let procs = toml.processes.unwrap_or_default();
        let json = toml.json.unwrap_or_default();

        Theme {
            numbers: NumberTheme {
                number: numbers.number.unwrap_or(s().fg(Color::Cyan)),
            },
            urls: UrlTheme {
                http: urls.http.unwrap_or(s().fg(Color::Red).faint()),
                https: urls.https.unwrap_or(s().fg(Color::Green).faint()),
                host: urls.host.unwrap_or(s().fg(Color::Blue).faint()),
                path: urls.path.unwrap_or(s().fg(Color::Blue)),
                query_params_key: urls.query_params_key.unwrap_or(s().fg(Color::Magenta)),
                query_params_value: urls.query_params_value.unwrap_or(s().fg(Color::Cyan)),
                symbols: urls.symbols.unwrap_or(s().fg(Color::Red)),
            },
            pointers: PointerTheme {
                number: pointers.number.unwrap_or(s().fg(Color::Blue).italic()),
                letter: pointers.letter.unwrap_or(s().fg(Color::Magenta).italic()),
                separator: pointers.separator.unwrap_or(s().faint()),
                x: pointers.x.unwrap_or(s().fg(Color::Red)),
            },
            dates: DateTheme {
                date: dates.date.unwrap_or(s().fg(Color::Magenta)),
                time: dates.time.unwrap_or(s().fg(Color::Blue)),
                zone: dates.zone.unwrap_or(s().fg(Color::Red)),
                separator: dates.separator.unwrap_or(s().faint()),
            },
            paths: PathTheme {
                segment: paths.segment.unwrap_or(s().fg(Color::Green)),
                separator: paths.separator.unwrap_or(s().fg(Color::Yellow)),
            },
            quotes: QuotesTheme {
                style: quotes.style.unwrap_or(s().fg(Color::Yellow)),
                quotes_token: quotes.quotes_token.unwrap_or('"'),
            },
            key_value_pairs: KeyValueTheme {
                key: kv.key.unwrap_or(s().faint()),
                separator: kv.separator.unwrap_or(s().fg(Color::White)),
            },
            uuids: UuidTheme {
                number: uuids.number.unwrap_or(s().fg(Color::Blue).italic()),
                letter: uuids.letter.unwrap_or(s().fg(Color::Magenta).italic()),
                dash: uuids.dash.unwrap_or(s().fg(Color::Red)),
            },
            ip_addresses: IpTheme {
                number: ips.number.unwrap_or(s().fg(Color::Blue).italic()),
                letter: ips.letter.unwrap_or(s().fg(Color::Magenta).italic()),
                separator: ips.separator.unwrap_or(s().fg(Color::Red)),
            },
            processes: ProcessTheme {
                name: procs.name.unwrap_or(s().fg(Color::Yellow)),
                id: procs.id.unwrap_or(s().fg(Color::Cyan)),
                bracket: procs.bracket.unwrap_or(s().fg(Color::Red)),
            },
            json: JsonTheme {
                key: json.key.unwrap_or(s().faint()),
                quote_token: json.quote_token.unwrap_or(s().faint()),
                curly_bracket: json.curly_bracket.unwrap_or(s().faint()),
                square_bracket: json.square_bracket.unwrap_or(s().faint()),
                comma: json.comma.unwrap_or(s().faint()),
                colon: json.colon.unwrap_or(s().faint()),
            },
            keywords: toml
                .keywords
                .into_iter()
                .map(|k| (k.style, k.words))
                .collect(),
            regexes: toml
                .regexes
                .into_iter()
                .map(|r| RegexTheme {
                    regex: r.regex,
                    style: r.style,
                })
                .collect(),
        }
    }

    pub fn default_theme() -> Theme {
        Theme::from_toml(TomlTheme::default())
    }
}

/// The keyword groups that are enabled unless `--disable-builtin-keywords`
/// is passed.
pub fn builtin_keywords() -> Vec<(Style, Vec<String>)> {
    let words = |ws: &[&str]| ws.iter().map(|w| w.to_string()).collect::<Vec<_>>();
    vec![
        (s().fg(Color::Red).italic(), words(&["null", "true", "false"])),
        (s().fg(Color::Red), words(&["ERROR"])),
        (s().fg(Color::Yellow), words(&["WARN"])),
        (s().fg(Color::White), words(&["INFO"])),
        (s().fg(Color::Green), words(&["DEBUG"])),
        (s().faint(), words(&["TRACE"])),
        (s().fg(Color::Green), words(&["SUCCESS"])),
        (s().fg(Color::Black).bg(Color::Green), words(&["GET"])),
        (s().fg(Color::Black).bg(Color::Yellow), words(&["POST"])),
        (s().fg(Color::Black).bg(Color::Magenta), words(&["PUT"])),
        (s().fg(Color::Black).bg(Color::Red), words(&["DELETE"])),
        (s().fg(Color::Black).bg(Color::Magenta), words(&["PATCH"])),
    ]
}

/// Merges keyword groups by style. Groups sharing a style are combined, and
/// the resulting map iterates in `Style` order.
pub fn group_keywords(groups: Vec<(Style, Vec<String>)>) -> BTreeMap<Style, Vec<String>> {
    let mut map: BTreeMap<Style, Vec<String>> = BTreeMap::new();
    for (style, words) in groups {
        map.entry(style).or_default().extend(words);
    }
    for words in map.values_mut() {
        words.sort();
        words.dedup();
    }
    map
}
EOF
echo ok"}

