/// The keyword groups that are enabled unless `--disable-builtin-keywords`
/// is passed.
pub fn builtin_keywords() -> Vec<(Style, Vec<String>)> {
    let words = |ws: &[&str]| ws.iter().map(|w| w.to_string()).collect::<Vec<_>>();
    vec![
        (s().fg(Color::Red).italic(), words(&["null", "true", "false"])),
        (s().fg(Color::Red), words(&["ERROR"])),
        (s().fg(Color::Yellow), words(&["WARN"])),
        (s().fg(Color::White), words(&["INFO"])),
        (s().fg(Color::Green), words(&["DEBUG"])),
        (s().faint(), words(&["TRACE"])),
        (s().fg(Color::Green), words(&["SUCCESS"])),
        (s().fg(Color::Black).bg(Color::Green), words(&["GET"])),
        (s().fg(Color::Black).bg(Color::Yellow), words(&["POST"])),
        (s().fg(Color::Black).bg(Color::Magenta), words(&["PUT"])),
        (s().fg(Color::Black).bg(Color::Red), words(&["DELETE"])),
        (s().fg(Color::Black).bg(Color::Magenta), words(&["PATCH"])),
    ]
}

/// Merges keyword groups by style. Groups sharing a style are combined, and
/// the resulting map iterates in `Style` order.
pub fn group_keywords(groups: Vec<(Style, Vec<String>)>) -> BTreeMap<Style, Vec<String>> {
    let mut map: BTreeMap<Style, Vec<String>> = BTreeMap::new();
    for (style, words) in groups {
        map.entry(style).or_default().extend(words);
    }
    for words in map.values_mut() {
        words.sort();
        words.dedup();
    }
    map
}
