use super::Highlighter;
use crate::style::Style;

/// Highlights quoted strings. A chunk with an odd number of quote characters
/// is left untouched.
pub struct QuoteHighlighter {
    quote: char,
    style: Style,
}

impl QuoteHighlighter {
    pub fn new(quote: char, style: Style) -> Self {
        QuoteHighlighter { quote, style }
    }
}

impl Highlighter for QuoteHighlighter {
    fn apply(&self, input: &str) -> String {
        let count = input.matches(self.quote).count();
        if count == 0 || count % 2 != 0 {
            return input.to_string();
        }

        let mut out = String::with_capacity(input.len() + 16);
        let mut rest = input;
        while let Some(start) = rest.find(self.quote) {
            let after_start = start + self.quote.len_utf8();
            let end_rel = rest[after_start..]
                .find(self.quote)
                .expect("even number of quotes");
            let end = after_start + end_rel + self.quote.len_utf8();
            out.push_str(&rest[..start]);
            self.style.paint_into(&mut out, &rest[start..end]);
            rest = &rest[end..];
        }
        out.push_str(rest);
        out
    }
}
