use regex::Regex;

use super::Highlighter;
use crate::style::Style;

/// Highlights `key=` pairs where the key is preceded by whitespace or the
/// start of the chunk.
pub struct KeyValueHighlighter {
    regex: Regex,
    key: Style,
    separator: Style,
}

impl KeyValueHighlighter {
    pub fn new(key: Style, separator: Style) -> Self {
        KeyValueHighlighter {
            regex: Regex::new(r"(?-u)(?P<pre>^|\s)(?P<key>\w+)(?P<eq>=)").expect("valid regex"),
            key,
            separator,
        }
    }
}

impl Highlighter for KeyValueHighlighter {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 16);
        let mut last = 0;
        for caps in self.regex.captures_iter(input) {
            let whole = caps.get(0).unwrap();
            out.push_str(&input[last..whole.start()]);
            out.push_str(caps.name("pre").map(|m| m.as_str()).unwrap_or(""));
            self.key.paint_into(&mut out, &caps["key"]);
            self.separator.paint_into(&mut out, &caps["eq"]);
            last = whole.end();
        }
        out.push_str(&input[last..]);
        out
    }
}
