use regex::Regex;

use super::Highlighter;
use crate::style::Style;

pub struct UuidHighlighter {
    regex: Regex,
    number: Style,
    letter: Style,
    dash: Style,
}

impl UuidHighlighter {
    pub fn new(number: Style, letter: Style, dash: Style) -> Self {
        UuidHighlighter {
            regex: Regex::new(
                r"(?-u)\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b",
            )
            .expect("valid regex"),
            number,
            letter,
            dash,
        }
    }
}

impl Highlighter for UuidHighlighter {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 64);
        let mut last = 0;
        for m in self.regex.find_iter(input) {
            out.push_str(&input[last..m.start()]);
            for ch in m.as_str().chars() {
                let mut buf = [0u8; 4];
                let s = ch.encode_utf8(&mut buf);
                if ch == '-' {
                    self.dash.paint_into(&mut out, s);
                } else if ch.is_ascii_digit() {
                    self.number.paint_into(&mut out, s);
                } else {
                    self.letter.paint_into(&mut out, s);
                }
            }
            last = m.end();
        }
        out.push_str(&input[last..]);
        out
    }
}
