use regex::Regex;

use super::Highlighter;
use crate::style::Style;

/// Highlights 32 and 64 bit hexadecimal pointers (`0x` followed by 8 or 16
/// hex digits). 64 bit pointers get a visual separator in the middle.
pub struct PointerHighlighter {
    regex: Regex,
    number: Style,
    letter: Style,
    separator: Style,
    x: Style,
}

impl PointerHighlighter {
    pub fn new(number: Style, letter: Style, separator: Style, x: Style) -> Self {
        PointerHighlighter {
            regex: Regex::new(r"(?-u)\b0[xX](?:[0-9a-fA-F]{16}|[0-9a-fA-F]{8})\b")
                .expect("valid regex"),
            number,
            letter,
            separator,
            x,
        }
    }
}

impl Highlighter for PointerHighlighter {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 64);
        let mut last = 0;
        for m in self.regex.find_iter(input) {
            out.push_str(&input[last..m.start()]);
            let text = m.as_str();
            let bytes = text.as_bytes();
            // "0"
            self.number.paint_into(&mut out, &text[0..1]);
            // "x" / "X"
            self.x.paint_into(&mut out, &text[1..2]);
            let hex = &text[2..];
            let is_64 = hex.len() == 16;
            for (i, _) in hex.bytes().enumerate() {
                if is_64 && i == 8 {
                    self.separator.paint_into(&mut out, "\u{2022}");
                }
                let s = &hex[i..i + 1];
                if bytes[i + 2].is_ascii_digit() {
                    self.number.paint_into(&mut out, s);
                } else {
                    self.letter.paint_into(&mut out, s);
                }
            }
            last = m.end();
        }
        out.push_str(&input[last..]);
        out
    }
}
