use regex::Regex;

use super::Highlighter;
use crate::style::Style;

/// Highlights unix process descriptions such as `systemd[1]`.
pub struct ProcessHighlighter {
    regex: Regex,
    name: Style,
    id: Style,
    bracket: Style,
}

impl ProcessHighlighter {
    pub fn new(name: Style, id: Style, bracket: Style) -> Self {
        ProcessHighlighter {
            regex: Regex::new(r"(?-u)(?P<name>\([^()]+\)|[\w/-]+)\[(?P<id>\d+)\]")
                .expect("valid regex"),
            name,
            id,
            bracket,
        }
    }
}

impl Highlighter for ProcessHighlighter {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 32);
        let mut last = 0;
        for caps in self.regex.captures_iter(input) {
            let whole = caps.get(0).unwrap();
            out.push_str(&input[last..whole.start()]);
            self.name.paint_into(&mut out, &caps["name"]);
            self.bracket.paint_into(&mut out, "[");
            self.id.paint_into(&mut out, &caps["id"]);
            self.bracket.paint_into(&mut out, "]");
            last = whole.end();
        }
        out.push_str(&input[last..]);
        out
    }
}
