use regex::Regex;

use super::Highlighter;
use crate::style::Style;

/// Highlights unix style file paths with at least two separators.
pub struct PathHighlighter {
    regex: Regex,
    segment: Style,
    separator: Style,
}

impl PathHighlighter {
    pub fn new(segment: Style, separator: Style) -> Self {
        PathHighlighter {
            regex: Regex::new(r"(?-u)(?:~|/?[\w.-]*)(?:/[\w.-]+){2,}").expect("valid regex"),
            segment,
            separator,
        }
    }
}

impl Highlighter for PathHighlighter {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 32);
        let mut last = 0;
        for m in self.regex.find_iter(input) {
            out.push_str(&input[last..m.start()]);
            let text = m.as_str();
            let mut seg_start = 0;
            for (i, b) in text.bytes().enumerate() {
                if b == b'/' {
                    if seg_start < i {
                        self.segment.paint_into(&mut out, &text[seg_start..i]);
                    }
                    self.separator.paint_into(&mut out, "/");
                    seg_start = i + 1;
                }
            }
            if seg_start < text.len() {
                self.segment.paint_into(&mut out, &text[seg_start..]);
            }
            last = m.end();
        }
        out.push_str(&input[last..]);
        out
    }
