//! Highlighting pipeline.
//!
//! A line is processed by a sequence of highlighters. Every highlighter only
//! ever sees the *plain* parts of a line: text that is already wrapped in ANSI
//! escape sequences (from earlier highlighters or from the input itself) is
//! left untouched and acts as a boundary for the matchers.

pub mod dates;
pub mod ip;
pub mod json;
pub mod keywords;
pub mod key_value;
pub mod numbers;
pub mod paths;
pub mod pointers;
pub mod processes;
pub mod quotes;
pub mod regexes;
pub mod urls;
pub mod uuids;

/// Something that can highlight a chunk of plain (escape-free) text.
pub trait Highlighter: Send + Sync {
    fn apply(&self, input: &str) -> String;
}

const ESC_START: &str = "\x1b[";
const ESC_RESET: &str = "\x1b[0m";

/// Applies `highlighter` to all plain chunks of `line`.
///
/// A styled chunk starts at an `ESC[` sequence and extends through the next
/// `ESC[0m` (inclusive); if there is no reset the styled chunk extends to the
/// end of the line. Empty plain chunks are skipped.
pub fn apply_to_plain_chunks(line: &str, highlighter: &dyn Highlighter) -> String {
    if !line.contains(ESC_START) {
        if line.is_empty() {
            return String::new();
        }
        return highlighter.apply(line);
    }

    let mut out = String::with_capacity(line.len() + 32);
    let mut rest = line;
    while let Some(i) = rest.find(ESC_START) {
        if i > 0 {
            out.push_str(&highlighter.apply(&rest[..i]));
        }
        let after = &rest[i..];
        match after.find(ESC_RESET) {
            Some(j) => {
                let end = j + ESC_RESET.len();
                out.push_str(&after[..end]);
                rest = &after[end..];
            }
            None => {
                out.push_str(after);
                return out;
            }
        }
    }
    if !rest.is_empty() {
        out.push_str(&highlighter.apply(rest));
    }
    out
}

/// An ordered collection of highlighters.
pub struct Pipeline {
    highlighters: Vec<Box<dyn Highlighter>>,
}

impl Pipeline {
    pub fn new(highlighters: Vec<Box<dyn Highlighter>>) -> Self {
        Pipeline { highlighters }
    }

    pub fn apply(&self, line: &str) -> String {
        let mut current = line.to_string();
        for h in &self.highlighters {
            current = apply_to_plain_chunks(&current, h.as_ref());
        }
        current
    }
}

/// True for ASCII letters, digits and underscore.
pub(crate) fn is_word_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}
