    x: Style,
}

impl PointerHighlighter {
    pub fn new(number: Style, letter: Style, separator: Style, x: Style) -> Self {
        PointerHighlighter {
            regex: Regex::new(r"(?-u)\b0[xX](?:[0-9a-fA-F]{16}|[0-9a-fA-F]{8})\b")
                .expect("valid regex"),
            number,
            letter,
            separator,
            x,
        }
    }
}

