            self.time.paint_into(&mut out, &caps["h"]);
            self.separator.paint_into(&mut out, ":");
            self.time.paint_into(&mut out, &caps["mi"]);
            self.separator.paint_into(&mut out, ":");
            self.time.paint_into(&mut out, &caps["s"]);
            if let Some(fs) = caps.name("fs") {
