            }
            if let Some(f) = caps.name("f") {
                self.time.paint_into(&mut out, f.as_str());
            }
            if let Some(z) = caps.name("z") {
                self.zone.paint_into(&mut out, z.as_str());
            }
            last = whole.end();
        }
        out.push_str(&input[last..]);
        out
    }
}

impl Highlighter for DateHighlighter {
    fn apply(&self, input: &str) -> String {
        let with_dates = self.date.apply(input);
        apply_to_plain_chunks(&with_dates, &self.time)
    }
}
