            regex: Regex::new(
                r"(?-u)(?P<scheme>https?)://(?P<host>[A-Za-z0-9._-]+)(?P<path>/[A-Za-z0-9._~%+/-]*)?(?P<query>\?[A-Za-z0-9_!%&'()*+,./:;=?@~-]*)?",
