            query_regex: Regex::new(
                r"(?-u)(?P<sym>[?&])(?P<key>[A-Za-z0-9._~%+-]*)=(?P<val>[A-Za-z0-9._~%+-]*)",
            )
            .expect("valid regex"),
            http,
            https,
            host,
            path,
            query_key,
            query_value,
            symbols,
        }
    }

    fn render_query(&self, out: &mut String, query: &str) {
        let mut last = 0;
        for caps in self.query_regex.captures_iter(query) {
            let whole = caps.get(0).unwrap();
            out.push_str(&query[last..whole.start()]);
            self.symbols.paint_into(out, &caps["sym"]);
            self.query_key.paint_into(out, &caps["key"]);
            self.symbols.paint_into(out, "=");
            self.query_value.paint_into(out, &caps["val"]);
            last = whole.end();
        }
        out.push_str(&query[last..]);
    }
}

