use regex::Regex;

use super::{apply_to_plain_chunks, Highlighter};
use crate::style::Style;

/// Highlights dates (`2023-01-02`, `01/02/2023`) and times (`10:11:12.123Z`).
pub struct DateHighlighter {
    date: DatePart,
    time: TimePart,
}

struct DatePart {
    regex: Regex,
    date: Style,
    separator: Style,
}

struct TimePart {
    regex: Regex,
    time: Style,
    zone: Style,
    separator: Style,
}

impl DateHighlighter {
    pub fn new(date: Style, time: Style, zone: Style, separator: Style) -> Self {
        let day = r"(?:0[1-9]|[12]\d|3[01])";
        let year = r"(?:19|20)\d{2}";
        let date_pattern = format!(
            r"(?-u)(?:(?P<y1>{year})(?P<s1>[-/])(?P<m1>{day})(?P<s2>[-/])(?P<d1>{day})|(?P<m2>{day})(?P<s3>[-/])(?P<d2>{day})(?P<s4>[-/])(?P<y2>{year}))",
            year = year,
            day = day
        );
        let time_pattern = r"(?-u)(?P<t>[T ])?(?P<h>[01]?\d|2[0-3]):(?P<mi>[0-5]\d):(?P<s>[0-5]\d)(?P<fs>[.,:])?(?P<f>\d+)?(?P<z>Z)?";
        DateHighlighter {
            date: DatePart {
                regex: Regex::new(&date_pattern).expect("valid regex"),
                date,
                separator,
            },
            time: TimePart {
                regex: Regex::new(time_pattern).expect("valid regex"),
                time,
                zone,
                separator,
            },
        }
    }
}

impl Highlighter for DatePart {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 32);
        let mut last = 0;
        for caps in self.regex.captures_iter(input) {
            let whole = caps.get(0).unwrap();
            out.push_str(&input[last..whole.start()]);
            let get = |name: &str| caps.name(name).map(|m| m.as_str()).unwrap_or("");
            if caps.name("y1").is_some() {
                self.date.paint_into(&mut out, get("y1"));
                self.separator.paint_into(&mut out, get("s1"));
                self.date.paint_into(&mut out, get("m1"));
                self.separator.paint_into(&mut out, get("s2"));
                self.date.paint_into(&mut out, get("d1"));
            } else {
                // Reconstructed in year-first order, mirroring the original tool.
                self.date.paint_into(&mut out, get("y2"));
                self.separator.paint_into(&mut out, get("s3"));
                self.date.paint_into(&mut out, get("m2"));
                self.separator.paint_into(&mut out, get("s4"));
                self.date.paint_into(&mut out, get("d2"));
            }
            last = whole.end();
        }
        out.push_str(&input[last..]);
        out
    }
}

impl Highlighter for TimePart {
    fn apply(&self, input: &str) -> String {
