use std::net::Ipv6Addr;

use regex::Regex;

use super::{apply_to_plain_chunks, Highlighter};
use crate::style::Style;

/// Highlights IPv6 (first) and IPv4 (second) addresses, with optional CIDR
/// suffixes.
pub struct IpHighlighter {
    v6: Ipv6Part,
    v4: Ipv4Part,
}

struct Ipv6Part {
    regex: Regex,
    number: Style,
    letter: Style,
    separator: Style,
}

struct Ipv4Part {
    regex: Regex,
    number: Style,
    separator: Style,
}

impl IpHighlighter {
    pub fn new(number: Style, letter: Style, separator: Style) -> Self {
        IpHighlighter {
            v6: Ipv6Part {
                regex: Regex::new(r"(?-u)(?P<addr>[0-9a-fA-F:.]+)(?:/(?P<cidr>\d+))?")
                    .expect("valid regex"),
                number,
                letter,
                separator,
            },
            v4: Ipv4Part {
                regex: Regex::new(
                    r"(?-u)\b(?P<a>\d{1,3})\.(?P<b>\d{1,3})\.(?P<c>\d{1,3})\.(?P<d>\d{1,3})(?:/(?P<cidr>\d{1,2}))?\b",
                )
                .expect("valid regex"),
                number,
                separator,
            },
        }
    }
}

fn is_ipv6_candidate(token: &str) -> bool {
    token.contains(':')
        && token.bytes().any(|b| b.is_ascii_hexdigit())
        && token.parse::<Ipv6Addr>().is_ok()
}

impl Highlighter for Ipv6Part {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 64);
        let mut last = 0;
        for caps in self.regex.captures_iter(input) {
            let whole = caps.get(0).unwrap();
            let addr = caps.name("addr").unwrap();
            if !is_ipv6_candidate(addr.as_str()) {
                continue;
            }
            out.push_str(&input[last..whole.start()]);
            for (i, b) in addr.as_str().bytes().enumerate() {
                let s = &addr.as_str()[i..i + 1];
                if b == b':' || b == b'.' {
                    self.separator.paint_into(&mut out, s);
                } else if b.is_ascii_digit() {
                    self.number.paint_into(&mut out, s);
                } else {
                    self.letter.paint_into(&mut out, s);
                }
            }
            if let Some(cidr) = caps.name("cidr") {
                self.separator.paint_into(&mut out, "/");
                self.number.paint_into(&mut out, cidr.as_str());
            }
            last = whole.end();
        }
        out.push_str(&input[last..]);
        out
    }
}

impl Highlighter for Ipv4Part {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 64);
        let mut last = 0;
        for caps in self.regex.captures_iter(input) {
            let whole = caps.get(0).unwrap();
            let octets = [&caps["a"], &caps["b"], &caps["c"], &caps["d"]];
            let valid_octets = octets
                .iter()
                .all(|o| o.parse::<u32>().map(|v| v <= 255).unwrap_or(false));
            let cidr = caps.name("cidr").map(|m| m.as_str());
            let valid_cidr = cidr
                .map(|c| c.parse::<u32>().map(|v| v <= 32).unwrap_or(false))
                .unwrap_or(true);
            if !valid_octets || !valid_cidr {
                continue;
            }
            out.push_str(&input[last..whole.start()]);
            for (i, octet) in octets.iter().enumerate() {
                if i > 0 {
                    self.separator.paint_into(&mut out, ".");
                }
                self.number.paint_into(&mut out, octet);
            }
            if let Some(c) = cidr {
                self.separator.paint_into(&mut out, "/");
                self.number.paint_into(&mut out, c);
            }
            last = whole.end();
        }
        out.push_str(&input[last..]);
        out
    }
}

impl Highlighter for IpHighlighter {
    fn apply(&self, input: &str) -> String {
        let with_v6 = self.v6.apply(input);
        apply_to_plain_chunks(&with_v6, &self.v4)
    }
}
