use serde_json::Value;

use super::Highlighter;
use crate::style::Style;

/// Re-renders chunks that are valid JSON documents with highlighted
/// structural tokens. Values (strings, numbers, booleans, null) are emitted
/// as plain text so later highlighters can process them.
pub struct JsonHighlighter {
    key: Style,
    quote_token: Style,
    curly_bracket: Style,
    square_bracket: Style,
    comma: Style,
    colon: Style,
}

impl JsonHighlighter {
    pub fn new(
        key: Style,
        quote_token: Style,
        curly_bracket: Style,
        square_bracket: Style,
        comma: Style,
        colon: Style,
    ) -> Self {
        JsonHighlighter {
            key,
            quote_token,
            curly_bracket,
            square_bracket,
            comma,
            colon,
        }
    }

    fn render(&self, out: &mut String, value: &Value) {
        match value {
            Value::Null => out.push_str("null"),
            Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
            Value::Number(n) => out.push_str(&n.to_string()),
            Value::String(s) => {
                self.quote_token.paint_into(out, "\"");
                out.push_str(s);
                self.quote_token.paint_into(out, "\"");
            }
            Value::Array(items) => {
                self.square_bracket.paint_into(out, "[");
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        self.comma.paint_into(out, ",");
                        out.push(' ');
                    }
                    self.render(out, item);
                }
                self.square_bracket.paint_into(out, "]");
            }
            Value::Object(map) => {
                self.curly_bracket.paint_into(out, "{");
                out.push(' ');
                for (i, (k, v)) in map.iter().enumerate() {
                    if i > 0 {
                        self.comma.paint_into(out, ",");
                        out.push(' ');
                    }
                    self.quote_token.paint_into(out, "\"");
                    self.key.paint_into(out, k);
                    self.quote_token.paint_into(out, "\"");
                    self.colon.paint_into(out, ":");
                    out.push(' ');
                    self.render(out, v);
                }
                out.push(' ');
                self.curly_bracket.paint_into(out, "}");
            }
        }
    }
}

impl Highlighter for JsonHighlighter {
    fn apply(&self, input: &str) -> String {
        match serde_json::from_str::<Value>(input) {
            Ok(value) => {
                let mut out = String::with_capacity(input.len() + 64);
                self.render(&mut out, &value);
                out
            }
            Err(_) => input.to_string(),
        }
    }
}
