use super::{is_word_byte, Highlighter};
use crate::style::Style;

/// Highlights a group of literal words sharing one style. Matches must not be
/// adjacent to ASCII word characters. Words with a background color are padded
/// with a space on each side.
pub struct KeywordHighlighter {
    regex: Regex,
    style: Style,
    padded: bool,
}

impl KeywordHighlighter {
    /// `words` must be sorted and de-duplicated.
    pub fn new(words: &[String], style: Style) -> Self {
        let pattern = words
            .iter()
            .map(|w| regex::escape(w))
            .collect::<Vec<_>>()
            .join("|");
        KeywordHighlighter {
            regex: Regex::new(&pattern).expect("escaped literals form a valid regex"),
            style,
            padded: style.bg.is_some(),
        }
    }
}

impl Highlighter for KeywordHighlighter {
    fn apply(&self, input: &str) -> String {
        let bytes = input.as_bytes();
        let mut out = String::with_capacity(input.len() + 16);
        let mut last = 0;
        for m in self.regex.find_iter(input) {
            let prev_ok = m.start() == 0 || !is_word_byte(bytes[m.start() - 1]);
            let next_ok = m.end() >= bytes.len() || !is_word_byte(bytes[m.end()]);
            if !prev_ok || !next_ok {
                continue;
            }
            out.push_str(&input[last..m.start()]);
            if self.padded {
                let padded = format!(" {} ", m.as_str());
                self.style.paint_into(&mut out, &padded);
            } else {
                self.style.paint_into(&mut out, m.as_str());
            }
            last = m.end();
        }
        out.push_str(&input[last..]);
        out
    }
}
