//! Terminal related helpers: size detection and capability sniffing.

use std::io::IsTerminal;

fn size_of_fd(fd: libc::c_int) -> Option<usize> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) != 0 {
            return None;
        }
        if ws.ws_col > 0 && ws.ws_row > 0 {
            Some(ws.ws_col as usize)
        } else {
            None
        }
    }
}

/// Width of the terminal attached to stdout, stderr or stdin (in that order).
pub fn terminal_width() -> Option<usize> {
    size_of_fd(libc::STDOUT_FILENO)
        .or_else(|| size_of_fd(libc::STDERR_FILENO))
        .or_else(|| size_of_fd(libc::STDIN_FILENO))
}

/// Whether the locale advertises UTF-8 support (used when stderr is a tty).
pub fn locale_supports_unicode() -> bool {
    if std::env::var("TERM").map(|t| t == "linux").unwrap_or(false) {
        return false;
    }
    let ctype = std::env::var("LC_ALL")
        .or_else(|_| std::env::var("LC_CTYPE"))
        .or_else(|_| std::env::var("LANG"))
        .unwrap_or_default()
        .to_uppercase();
    ctype.ends_with("UTF8") || ctype.ends_with("UTF-8")
}

fn env_is(var: &str, value: &str) -> bool {
    std::env::var(var).map(|v| v == value).unwrap_or(false)
}

fn env_nonzero_number(var: &str) -> Option<u32> {
    std::env::var(var).ok().and_then(|v| v.parse::<u32>().ok())
}

/// Mirrors the usual `supports-color` style detection for a stream.
pub fn stream_supports_color(is_tty: bool) -> bool {
    if let Ok(force) = std::env::var("FORCE_COLOR") {
        let level = match force.as_str() {
            "" | "true" => 1,
            "false" => 0,
            other => other.parse::<u32>().map(|n| n.min(3)).unwrap_or(1),
        };
        return level > 0;
    }
    if std::env::var_os("NO_COLOR").is_some() || env_is("TERM", "dumb") {
        return false;
    }
    let ignore_is_terminal = std::env::var("IGNORE_IS_TERMINAL")
        .map(|v| v != "0")
        .unwrap_or(false);
    if !(is_tty || ignore_is_terminal) {
        return false;
    }
    if env_is("COLORTERM", "truecolor") || env_is("TERM_PROGRAM", "iTerm.app") {
        return true;
    }
    if env_is("TERM_PROGRAM", "Apple_Terminal") {
        return true;
    }
    let term = std::env::var("TERM").unwrap_or_default();
    if term.ends_with("-256") || term.ends_with("-256color") || term.contains("256") {
        return true;
    }
    if std::env::var_os("COLORTERM").is_some()
        || check_ansi_color(&term)
        || std::env::var("CLICOLOR").map(|v| v != "0").unwrap_or(false)
        || is_ci()
    {
        return true;
    }
    let _ = env_nonzero_number("FORCE_COLOR");
    false
}

fn check_ansi_color(term: &str) -> bool {
    term.starts_with("screen")
        || term.starts_with("xterm")
        || term.starts_with("vt100")
        || term.starts_with("vt220")
        || term.starts_with("rxvt")
        || term.contains("color")
        || term.contains("ansi")
        || term.contains("cygwin")
        || term.contains("linux")
}

fn is_ci() -> bool {
    std::env::var_os("CI").is_some()
        || std::env::var_os("CONTINUOUS_INTEGRATION").is_some()
        || std::env::var_os("BUILD_NUMBER").is_some()
        || std::env::var_os("RUN_ID").is_some()
        || std::env::var_os("TRAVIS").is_some()
        || std::env::var_os("GITHUB_ACTIONS").is_some()
        || std::env::var_os("GITLAB_CI").is_some()
}

pub fn stdout_is_tty() -> bool {
    std::io::stdout().is_terminal()
}

pub fn stdin_is_tty() -> bool {
    std::io::stdin().is_terminal()
}
