#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct Report {
    pub severity: Severity,
    pub code: Option<String>,
    pub message: String,
    pub causes: Vec<String>,
    pub help: Option<String>,
}

impl Report {
    pub fn error(message: impl Into<String>) -> Self {
        Report {
            severity: Severity::Error,
            code: None,
            message: message.into(),
            causes: Vec::new(),
            help: None,
        }
    }

    pub fn warning(message: impl Into<String>) -> Self {
        Report {
            severity: Severity::Warning,
            code: None,
            message: message.into(),
            causes: Vec::new(),
            help: None,
        }
    }

    pub fn with_code(mut self, code: impl Into<String>) -> Self {
        self.code = Some(code.into());
        self
    }

    pub fn with_cause(mut self, cause: impl Into<String>) -> Self {
        self.causes.push(cause.into());
        self
    }

    pub fn with_help(mut self, help: impl Into<String>) -> Self {
        self.help = Some(help.into());
        self
    }

    /// Renders the report the way it is printed when returned from `main`.
    pub fn render(&self) -> String {
        let theme = ReportTheme::detect();
        let width = term::terminal_width().unwrap_or(80);

        let (icon, sev_color) = match self.severity {
            Severity::Error => (theme.chars.error, "31"),
            Severity::Warning => (theme.chars.warning, "33"),
        };

        let mut out = String::new();
        out.push_str("Error: ");

        if let Some(code) = &self.code {
            out.push_str(&theme.style(sev_color, code));
            out.push('\n');
            out.push('\n');
        }

        // Message
        let initial = format!("  {} ", theme.style(sev_color, icon));
        let rest = format!("  {} ", theme.style(sev_color, theme.chars.vbar));
        let w = width.saturating_sub(2);
        out.push_str(&wrap::fill(&self.message, w, &initial, &rest));
        out.push('\n');

