        if let Some(help) = &self.help {
            let w = width.saturating_sub(4);
            let initial = theme.style("36", "  help: ");
            out.push_str(&wrap::fill(help, w, &initial, "        "));
            out.push('\n');
        }

        out
    }

    /// Prints the report to stderr.
    pub fn eprint(&self) {
        eprintln!("{}", self.render());
    }
}

