use crate::highlight::quotes::QuoteHighlighter;
use crate::highlight::regexes::RegexHighlighter;
use crate::highlight::urls::UrlHighlighter;
use crate::highlight::uuids::UuidHighlighter;
use crate::highlight::{Highlighter, Pipeline};
use crate::report::Report;
use crate::theme::{builtin_keywords, group_keywords, Theme};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Group {
    Numbers,
    Urls,
    Pointers,
    Dates,
    Paths,
    Quotes,
    KeyValuePairs,
    Uuids,
    IpAddresses,
    Processes,
    Json,
}

impl Group {
    fn from_name(name: &str) -> Option<Group> {
        Some(match name {
            "numbers" => Group::Numbers,
            "urls" => Group::Urls,
            "pointers" => Group::Pointers,
            "dates" => Group::Dates,
            "paths" => Group::Paths,
            "quotes" => Group::Quotes,
            "key-value-pairs" => Group::KeyValuePairs,
            "uuids" => Group::Uuids,
            "ip-addresses" => Group::IpAddresses,
            "processes" => Group::Processes,
            "json" => Group::Json,
            _ => return None,
        })
    }
}

/// Validates the `--enable` / `--disable` combination.
pub fn validate_groups(cli: &Cli) -> Result<(), Report> {
    if !cli.enabled.is_empty() && !cli.disabled.is_empty() {
        return Err(Report::error(
            "cannot both enable and disable highlighters",
        ));
    }
    Ok(())
}

pub fn build_pipeline(theme: &Theme, cli: &Cli) -> Result<Pipeline, Report> {
    let enabled: Vec<Group> = cli.enabled.iter().filter_map(|n| Group::from_name(n)).collect();
    let disabled: Vec<Group> = cli.disabled.iter().filter_map(|n| Group::from_name(n)).collect();
    let is_on = |g: Group| -> bool {
        if !enabled.is_empty() {
            enabled.contains(&g)
        } else {
            !disabled.contains(&g)
        }
    };

    let mut highlighters: Vec<Box<dyn Highlighter>> = Vec::new();

    for regex in &theme.regexes {
        match RegexHighlighter::new(&regex.regex, regex.style) {
            Ok(h) => highlighters.push(Box::new(h)),
            Err(e) => {
                let msg = e.to_string();
                return Err(Report::error(format!("Regex error: {}", msg))
                    .with_cause(msg)
                    .with_help("Verify that your regex pattern is valid."));
            }
        }
    }

    if is_on(Group::Json) {
        let j = &theme.json;
        highlighters.push(Box::new(JsonHighlighter::new(
            j.key,
            j.quote_token,
            j.curly_bracket,
            j.square_bracket,
            j.comma,
            j.colon,
        )));
    }
    if is_on(Group::Dates) {
        let d = &theme.dates;
        highlighters.push(Box::new(DateHighlighter::new(
            d.date,
            d.time,
            d.zone,
            d.separator,
        )));
    }
    if is_on(Group::IpAddresses) {
        let i = &theme.ip_addresses;
        highlighters.push(Box::new(IpHighlighter::new(i.number, i.letter, i.separator)));
    }
    if is_on(Group::Urls) {
        let u = &theme.urls;
        highlighters.push(Box::new(UrlHighlighter::new(
            u.http,
            u.https,
            u.host,
            u.path,
            u.query_params_key,
            u.query_params_value,
            u.symbols,
        )));
    }
    if is_on(Group::Paths) {
        let p = &theme.paths;
        highlighters.push(Box::new(PathHighlighter::new(p.segment, p.separator)));
    }
    if is_on(Group::Uuids) {
        let u = &theme.uuids;
        highlighters.push(Box::new(UuidHighlighter::new(u.number, u.letter, u.dash)));
    }
    if is_on(Group::KeyValuePairs) {
        let k = &theme.key_value_pairs;
        highlighters.push(Box::new(KeyValueHighlighter::new(k.key, k.separator)));
    }
    if is_on(Group::Pointers) {
        let p = &theme.pointers;
        highlighters.push(Box::new(PointerHighlighter::new(
            p.number,
            p.letter,
            p.separator,
            p.x,
        )));
    }
    if is_on(Group::Processes) {
        let p = &theme.processes;
        highlighters.push(Box::new(ProcessHighlighter::new(p.name, p.id, p.bracket)));
    }
    if is_on(Group::Numbers) {
        highlighters.push(Box::new(NumberHighlighter::new(theme.numbers.number)));
    }

    // Keywords: builtin + config + CLI, merged by style and applied in style order.
    let mut groups = Vec::new();
    if !cli.disable_builtin_keywords {
        groups.extend(builtin_keywords());
    }
    groups.extend(theme.keywords.iter().cloned());
    for HighlightArg { style, words } in &cli.highlights {
        groups.push((*style, words.clone()));
    }
    for (style, words) in group_keywords(groups) {
        if words.is_empty() {
            continue;
        }
        highlighters.push(Box::new(KeywordHighlighter::new(&words, style)));
    }

    if is_on(Group::Quotes) {
        let q = &theme.quotes;
        highlighters.push(Box::new(QuoteHighlighter::new(q.quotes_token, q.style)));
    }

    Ok(Pipeline::new(highlighters))
}
