//! Locating and loading the theme configuration file.

use std::path::PathBuf;

use crate::report::Report;
use crate::theme::{Theme, TomlTheme};

fn default_config_path() -> Option<PathBuf> {
    if let Some(xdg) = std::env::var_os("XDG_CONFIG_HOME") {
        return Some(PathBuf::from(xdg).join("tailspin").join("theme.toml"));
    }
    let home = std::env::var_os("HOME")?;
    Some(PathBuf::from(home).join(".config").join("tailspin").join("theme.toml"))
}

fn parse_theme(contents: &str) -> Result<Theme, Report> {
    match toml::from_str::<TomlTheme>(contents) {
        Ok(t) => Ok(Theme::from_toml(t)),
        Err(e) => Err(Report::error(e.to_string())),
    }
}

pub fn load_theme(config_path: Option<&str>) -> Result<Theme, Report> {
    match config_path {
        Some(path) => {
            let path = PathBuf::from(path);
            if !path.exists() {
                return Err(Report::error("could not find the TOML file"));
            }
            let contents = std::fs::read_to_string(&path).map_err(|e| {
                Report::error(format!("could not read the TOML file: {}", e)).with_cause(e.to_string())
            })?;
            parse_theme(&contents)
        }
        None => {
            let Some(path) = default_config_path() else {
                return Ok(Theme::default_theme());
            };
            if !path.exists() {
                return Ok(Theme::default_theme());
            }
            let contents = std::fs::read_to_string(&path).map_err(|e| {
                Report::error(format!("could not read the TOML file: {}", e)).with_cause(e.to_string())
            })?;
            parse_theme(&contents)
        }
    }
}
