//! Following a file for appended content using inotify.

use std::ffi::{CString, OsStr};
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read, Seek, SeekFrom};
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};

/// Watches a file (via its parent directory) and yields newly appended lines.
pub struct FileFollower {
    path: PathBuf,
    file_name: Vec<u8>,
    inotify_fd: libc::c_int,
    reader: Option<BufReader<File>>,
    position: u64,
}

pub enum FollowError {
    Io(io::Error),
    Line(io::Error),
}

impl FileFollower {
    /// Starts following `path` from byte offset `position`.
    pub fn new(path: &Path, position: u64) -> io::Result<Self> {
        let abs = if path.is_absolute() {
            path.to_path_buf()
        } else {
            std::env::current_dir()?.join(path)
        };
        let parent = abs.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("/"));
        let parent = if parent.as_os_str().is_empty() { PathBuf::from(".") } else { parent };
        let file_name = abs
            .file_name()
            .map(|n| n.as_bytes().to_vec())
            .unwrap_or_default();

        let fd = unsafe { libc::inotify_init1(libc::IN_CLOEXEC) };
        if fd < 0 {
            return Err(io::Error::last_os_error());
        }
        let c_parent = CString::new(parent.as_os_str().as_bytes())
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid path"))?;
        let mask = libc::IN_MODIFY
            | libc::IN_CREATE
            | libc::IN_MOVED_TO
            | libc::IN_DELETE
            | libc::IN_MOVED_FROM
            | libc::IN_ATTRIB
            | libc::IN_CLOSE_WRITE;
        let wd = unsafe { libc::inotify_add_watch(fd, c_parent.as_ptr(), mask) };
        if wd < 0 {
            let err = io::Error::last_os_error();
            unsafe { libc::close(fd) };
            return Err(err);
        }

        let mut follower = FileFollower {
            path: abs,
            file_name,
            inotify_fd: fd,
            reader: None,
            position,
        };
        follower.open(position)?;
        Ok(follower)
    }

    fn open(&mut self, position: u64) -> io::Result<()> {
        let mut file = File::open(&self.path)?;
        file.seek(SeekFrom::Start(position))?;
        self.reader = Some(BufReader::new(file));
        self.position = position;
        Ok(())
    }

    /// Blocks until something happens to the watched file, then reads all
    /// newly available complete lines (and a trailing partial line, if any),
    /// calling `emit` for each one.
    pub fn wait_and_read(
        &mut self,
        emit: &mut dyn FnMut(&str) -> io::Result<()>,
    ) -> Result<(), FollowError> {
        let mut buf = [0u8; 4096];
        let n = unsafe {
            libc::read(
                self.inotify_fd,
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
            )
        };
        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                return Ok(());
            }
            return Err(FollowError::Io(err));
        }
        let n = n as usize;
        let mut relevant = false;
        let mut recreated = false;
        let mut offset = 0;
        let header = std::mem::size_of::<libc::inotify_event>();
        while offset + header <= n {
            let ev = unsafe { &*(buf[offset..].as_ptr() as *const libc::inotify_event) };
            let name_len = ev.len as usize;
            let name_start = offset + header;
            let name_end = (name_start + name_len).min(n);
            let name_bytes = &buf[name_start..name_end];
            let name = name_bytes.split(|b| *b == 0).next().unwrap_or(&[]);
            if OsStr::from_bytes(name) == OsStr::from_bytes(&self.file_name) {
                relevant = true;
                if ev.mask & (libc::IN_CREATE | libc::IN_MOVED_TO) != 0 {
                    recreated = true;
                }
            }
            offset = name_end;
        }
        if !relevant {
            return Ok(());
        }
        if recreated {
            // The file was replaced; start again from the beginning.
            if self.open(0).is_err() {
                self.reader = None;
                return Ok(());
            }
        }
        self.read_available(emit)
    }

    fn read_available(
        &mut self,
        emit: &mut dyn FnMut(&str) -> io::Result<()>,
    ) -> Result<(), FollowError> {
        if self.reader.is_none() && self.open(0).is_err() {
            return Ok(());
        }
        // Detect truncation.
        if let Ok(meta) = std::fs::metadata(&self.path) {
            if meta.len() < self.position {
                if self.open(0).is_err() {
                    self.reader = None;
                    return Ok(());
                }
            }
        }
        let reader = match self.reader.as_mut() {
            Some(r) => r,
            None => return Ok(()),
        };
        loop {
            let mut line = String::new();
            match reader.read_line(&mut line) {
                Ok(0) => break,
                Ok(n) => {
                    self.position += n as u64;
                    if line.ends_with('\n') {
                        line.pop();
                    }
                    emit(&line).map_err(FollowError::Io)?;
                }
                Err(e) => return Err(FollowError::Line(e)),
            }
        }
        Ok(())
    }
}

impl Drop for FileFollower {
    fn drop(&mut self) {
        unsafe {
            libc::close(self.inotify_fd);
        }
    }
}

/// Reads the whole file strictly as UTF-8.
pub fn read_initial(path: &Path) -> io::Result<(String, u64)> {
    let mut file = File::open(path)?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes)?;
    let len = bytes.len() as u64;
    let text = String::from_utf8(bytes)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "stream did not contain valid UTF-8"))?;
    Ok((text, len))
}
EOF
