/// A parsed pager command, where `[FILE]` placeholders are substituted.
#[derive(Debug, Clone)]
pub enum PagerCommand {
    Default,
    Custom(Vec<String>),
}

impl PagerCommand {
    pub fn parse(custom: Option<&str>) -> Result<PagerCommand, Report> {
        match custom {
            None => Ok(PagerCommand::Default),
            Some(cmd) => {
                let parts = shlex::split(cmd).unwrap_or_default();
                if parts.is_empty() || !parts.iter().any(|p| p.contains("[FILE]")) {
                    return Err(Report::error("Could not parse custom pager command"));
                }
                Ok(PagerCommand::Custom(parts))
            }
        }
    }

    fn build(&self, file: &Path, follow: bool) -> Command {
        match self {
            PagerCommand::Default => {
                let mut cmd = Command::new("less");
                if follow {
                    cmd.arg("+F");
                }
                cmd.arg("--ignore-case")
                    .arg("--RAW-CONTROL-CHARS")
                    .arg("--")
                    .arg(file);
                cmd.env("LESSSECURE", "1");
                cmd
            }
            PagerCommand::Custom(parts) => {
                let file_str = file.to_string_lossy();
                let args: Vec<String> = parts
                    .iter()
                    .map(|p| p.replace("[FILE]", &file_str))
                    .collect();
                let mut cmd = Command::new(&args[0]);
                cmd.args(&args[1..]);
                cmd
            }
        }
    }

    /// Runs the pager on `file` and waits for it to exit.
    pub fn run(&self, file: &Path, follow: bool) -> Result<ExitStatus, Report> {
        let mut cmd = self.build(file, follow);
        cmd.stdin(Stdio::inherit())
            .stdout(Stdio::inherit())
            .stderr(Stdio::inherit());
        unsafe {
            cmd.pre_exec(|| {
                libc::signal(libc::SIGINT, libc::SIG_DFL);
                Ok(())
            });
        }
        let mut child = cmd.spawn().map_err(|e| {
            Report::error("Could not run pager")
                .with_code("less::command_spawn")
                .with_cause(e.to_string())
        })?;
        let status = child.wait().map_err(|e| {
            Report::error("Could not run pager")
                .with_code("less::command_spawn")
                .with_cause(e.to_string())
        })?;
        Ok(status)
    }
}

/// Temporary directory holding the highlighted output presented to the pager.
pub struct TempOutput {
    dir: PathBuf,
    pub path: PathBuf,
}

fn random_bytes(n: usize) -> Vec<u8> {
    let mut buf = vec![0u8; n];
    if let Ok(mut f) = File::open("/dev/urandom") {
        if f.read_exact(&mut buf).is_ok() {
            return buf;
        }
    }
    // Fallback: derive from the clock and pid.
    let seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0)
        ^ (std::process::id() as u64).rotate_left(32);
    let mut x = seed | 1;
    for b in buf.iter_mut() {
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        *b = (x & 0xff) as u8;
    }
    buf
