    )
}

impl TempOutput {
    pub fn create() -> io::Result<TempOutput> {
        let base = std::env::temp_dir();
        let mut attempts = 0;
        loop {
            let dir = base.join(format!(".tmp{}", random_alnum(6)));
            match std::fs::create_dir(&dir) {
                Ok(()) => {
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::PermissionsExt;
                        let _ = std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o700));
                    }
                    let path = dir.join(format!("tailspin.temp.{}", random_uuid_v4()));
                    File::create(&path)?;
                    return Ok(TempOutput { dir, path });
                }
                Err(e) if e.kind() == io::ErrorKind::AlreadyExists && attempts < 1000 => {
                    attempts += 1;
                }
                Err(e) => return Err(e),
            }
        }
    }

    pub fn open_append(&self) -> io::Result<File> {
        OpenOptions::new().append(true).open(&self.path)
    }

    pub fn cleanup(&self) {
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

/// A line writer that appends to the temporary file and flushes eagerly.
pub struct TempFileWriter {
    file: File,
}

impl TempFileWriter {
    pub fn new(file: File) -> Self {
        TempFileWriter { file }
    }

    pub fn write_line(&mut self, line: &str) -> io::Result<()> {
        self.file.write_all(line.as_bytes())?;
        self.file.write_all(b"\n")
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.file.flush()
    }
}
