use std::path::{Path, PathBuf};
use std::sync::Arc;

use highlight::Pipeline;
use pager::{PagerCommand, TempFileWriter, TempOutput};
use report::Report;

enum Source {
    File(PathBuf),
    Stdin,
    Exec(String),
}

fn yellow(text: &str) -> String {
    format!("\x1b[33m{}\x1b[0m", text)
}

fn magenta(text: &str) -> String {
    format!("\x1b[35m{}\x1b[0m", text)
}

fn cyan(text: &str) -> String {
    format!("\x1b[36m{}\x1b[0m", text)
}

/// Mimics the message printed when a worker thread fails to print to stdout.
fn report_broken_pipe(err: &io::Error) {
    eprintln!();
    eprintln!(
        "thread 'tokio-runtime-worker' ({}) panicked at /rustc/ac68faa20c58cbccd01ee7208bf3b6e93a7d7f96/library/std/src/io/stdio.rs:1165:9:",
        std::process::id()
    );
    eprintln!("failed printing to stdout: {}", err);
    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
}

fn initial_read_failed() -> Report {
    Report::error("Failed to receive initial-read-complete signal")
        .with_cause("channel closed")
        .with_help("Ensure the IO task completes correctly and signals initial read completion.")
}

fn resolve_source(cli: &cli::Cli) -> Result<Option<Source>, Report> {
    if let Some(file) = &cli.file {
        if cli.exec.is_some() {
            return Err(Report::error(format!(
                "Cannot read from both file and {}",
                magenta("--listen-command")
            )));
        }
        let path = PathBuf::from(file);
        if !path.exists() {
            return Err(Report::warning(format!(
                "{}: No such file or directory",
                yellow(file)
            )));
        }
        if !path.is_file() {
            return Err(Report::error("Path is not a file"));
        }
        return Ok(Some(Source::File(path)));
    }
    if !term::stdin_is_tty() {
        return Ok(Some(Source::Stdin));
    }
    if let Some(cmd) = &cli.exec {
        return Ok(Some(Source::Exec(cmd.clone())));
    }
    Ok(None)
}

fn open_error(path: &Path, err: io::Error) -> Report {
    Report::error(format!("Could not open file: {:?}", path.display().to_string()))
        .with_cause(err.to_string())
}

/// Reads and highlights the existing content of a file, feeding each line to
/// `emit`. Returns the number of bytes consumed.
fn initial_file_read(
    path: &Path,
    pipeline: &Pipeline,
    emit: &mut dyn FnMut(&str) -> io::Result<()>,
) -> Result<u64, Report> {
    let (text, len) = match follow::read_initial(path) {
        Ok(v) => v,
        Err(e) if e.kind() == io::ErrorKind::InvalidData => return Err(initial_read_failed()),
        Err(e) => return Err(open_error(path, e)),
    };
    for line in text.split_inclusive('\n') {
        let line = line.strip_suffix('\n').unwrap_or(line);
        let highlighted = pipeline.apply(line);
        if let Err(e) = emit(&highlighted) {
            if e.kind() == io::ErrorKind::BrokenPipe {
                report_broken_pipe(&e);
                return Err(initial_read_failed());
            }
            return Err(Report::error(e.to_string()));
        }
    }
    Ok(len)
}

fn run_print_file(path: &Path, follow: bool, pipeline: &Pipeline) -> Result<i32, Report> {
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    let mut emit = |line: &str| -> io::Result<()> {
        out.write_all(line.as_bytes())?;
        out.write_all(b"\n")
    };
    let position = initial_file_read(path, pipeline, &mut emit)?;
    if let Err(e) = out.flush() {
        if e.kind() == io::ErrorKind::BrokenPipe {
            report_broken_pipe(&e);
            return Err(initial_read_failed());
        }
        return Err(Report::error(e.to_string()));
    }
    if !follow {
        return Ok(0);
    }

    let mut follower = follow::FileFollower::new(path, position)
        .map_err(|e| Report::error("Could not read next line").with_cause(e.to_string()))?;
    loop {
        let mut emit = |line: &str| -> io::Result<()> {
            let highlighted = pipeline.apply(line);
            out.write_all(highlighted.as_bytes())?;
            out.write_all(b"\n")?;
            out.flush()
        };
        match follower.wait_and_read(&mut emit) {
            Ok(()) => {}
            Err(follow::FollowError::Line(e)) => {
                return Err(Report::error("Could not read next line").with_cause(e.to_string()));
            }
            Err(follow::FollowError::Io(e)) => {
                if e.kind() == io::ErrorKind::BrokenPipe {
                    report_broken_pipe(&e);
                    return Ok(1);
                }
                return Err(Report::error("Could not read next line").with_cause(e.to_string()));
            }
        }
    }
}

fn run_print_stdin(pipeline: &Pipeline) -> Result<i32, Report> {
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    let result = {
        let mut emit = |line: &str| -> io::Result<()> {
            let highlighted = pipeline.apply(line);
            out.write_all(highlighted.as_bytes())?;
            out.write_all(b"\n")
        };
        let mut flush = || -> io::Result<()> { Ok(()) };
        input::read_stdin(&mut emit, &mut flush)
    };
    let flushed = out.flush();
    match result {
        Ok(()) => {}
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => {
            report_broken_pipe(&e);
            return Err(initial_read_failed());
        }
        Err(e) => return Err(Report::error(e.to_string())),
    }
    if let Err(e) = flushed {
        if e.kind() == io::ErrorKind::BrokenPipe {
            report_broken_pipe(&e);
            return Err(initial_read_failed());
        }
        return Err(Report::error(e.to_string()));
    }
    Ok(0)
}

fn ignore_sigint() {
    unsafe {
        libc::signal(libc::SIGINT, libc::SIG_IGN);
    }
}

fn pager_status_to_result(status: std::process::ExitStatus) -> Result<i32, Report> {
    if status.success() {
        Ok(0)
    } else {
        Err(Report::error(format!(
            "Pager exited with non-zero status: {}",
            status
        ))
        .with_code("less::non_zero_exit"))
    }
}

fn run_pager_file(
    path: &Path,
    follow: bool,
    pipeline: Arc<Pipeline>,
    pager: &PagerCommand,
) -> Result<i32, Report> {
    let temp = TempOutput::create().map_err(|e| Report::error(e.to_string()))?;
    let result = (|| {
        let mut writer = TempFileWriter::new(
            temp.open_append().map_err(|e| Report::error(e.to_string()))?,
        );
        let mut emit = |line: &str| -> io::Result<()> { writer.write_line(line) };
        let position = initial_file_read(path, &pipeline, &mut emit)?;
        writer.flush().map_err(|e| Report::error(e.to_string()))?;

        ignore_sigint();

        if follow {
            let path = path.to_path_buf();
            let pipeline = Arc::clone(&pipeline);
            std::thread::Builder::new()
                .name("tokio-runtime-worker".into())
                .spawn(move || {
                    let mut follower = match follow::FileFollower::new(&path, position) {
                        Ok(f) => f,
                        Err(_) => return,
                    };
                    loop {
                        let mut emit = |line: &str| -> io::Result<()> {
                            let highlighted = pipeline.apply(line);
                            writer.write_line(&highlighted)?;
                            writer.flush()
                        };
                        if follower.wait_and_read(&mut emit).is_err() {
                            return;
                        }
                    }
                })
                .map_err(|e| Report::error(e.to_string()))?;
        }

        let status = pager.run(&temp.path, follow)?;
        pager_status_to_result(status)
    })();
    temp.cleanup();
    result
}

fn run_pager_exec(command: &str, pipeline: Arc<Pipeline>, pager: &PagerCommand) -> Result<i32, Report> {
    let temp = TempOutput::create().map_err(|e| Report::error(e.to_string()))?;
    let result = (|| {
        let mut writer = TempFileWriter::new(
            temp.open_append().map_err(|e| Report::error(e.to_string()))?,
        );

        ignore_sigint();

        let mut child = input::spawn_command(command).map_err(|e| {
            Report::error("Could not run command").with_cause(e.to_string())
        })?;
        let pipeline = Arc::clone(&pipeline);
        std::thread::Builder::new()
            .name("tokio-runtime-worker".into())
            .spawn(move || {
                let mut emit = |line: &str| -> io::Result<()> {
                    let highlighted = pipeline.apply(line);
                    writer.write_line(&highlighted)
                };
                let mut flush = || -> io::Result<()> { writer.flush() };
                let _ = input::read_child_lines(&mut child, &mut emit, &mut flush);
                let _ = child.wait();
            })
            .map_err(|e| Report::error(e.to_string()))?;

        let status = pager.run(&temp.path, true)?;
        pager_status_to_result(status)
    })();
    temp.cleanup();
    result
}

fn run(cli: cli::Cli) -> Result<i32, Report> {
    let source = match resolve_source(&cli)? {
        Some(s) => s,
        None => {
            println!("Missing filename ({} for help)", cyan("tspin --help"));
            return Ok(0);
        }
    };

    let print = cli.print || matches!(source, Source::Stdin);
    let pager = if print {
        PagerCommand::Default
    } else {
        PagerCommand::parse(cli.pager.as_deref())?
    };

    pipeline::validate_groups(&cli)?;

    if print && matches!(source, Source::Exec(_)) {
        return Ok(0);
    }

    let theme = config::load_theme(cli.config_path.as_deref())?;
    let pipeline = Arc::new(pipeline::build_pipeline(&theme, &cli)?);

    match (source, print) {
        (Source::Stdin, _) => run_print_stdin(&pipeline),
        (Source::File(path), true) => run_print_file(&path, cli.follow, &pipeline),
        (Source::File(path), false) => run_pager_file(&path, cli.follow, pipeline, &pager),
        (Source::Exec(cmd), false) => run_pager_exec(&cmd, pipeline, &pager),
        (Source::Exec(_), true) => Ok(0),
    }
}

fn main() {
    let cli = cli::parse();
    match run(cli) {
        Ok(code) => std::process::exit(code),
        Err(report) => {
            report.eprint();
            std::process::exit(1);
        }
    }
}
