        let mut words = Vec::new();
        let mut start = 0;
        let mut in_whitespace = false;
        for (idx, ch) in line.char_indices() {
            if in_whitespace && ch != ' ' {
                words.push(Word::from(&line[start..idx]));
                start = idx;
            }
            in_whitespace = ch == ' ';
        }
        if start < line.len() {
            words.push(Word::from(&line[start..]));
        }
        words
