//! A tiny, self-contained implementation of the `terminal_size` API.
//!
//! It only provides what is needed by `clap`'s `wrap_help` feature: querying
//! the dimensions of the terminal attached to stdout, stderr or stdin.

use std::os::fd::{AsFd, AsRawFd};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

fn size_of_raw_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    // SAFETY: plain libc calls on an integer file descriptor; `winsize` is a
    // POD struct that is fully initialised by the kernel on success.
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) != 0 {
            return None;
        }
        if ws.ws_col > 0 && ws.ws_row > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal behind the given file descriptor.
pub fn terminal_size_of<Fd: AsFd>(fd: Fd) -> Option<(Width, Height)> {
    size_of_raw_fd(fd.as_fd().as_raw_fd())
}

/// Returns the size of the terminal, trying stdout, stderr and stdin in turn.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_raw_fd(libc::STDOUT_FILENO)
        .or_else(|| size_of_raw_fd(libc::STDERR_FILENO))
        .or_else(|| size_of_raw_fd(libc::STDIN_FILENO))
}
