/// Reads a byte stream, emitting one line at a time.
///
/// Buffered data containing at least two complete lines is converted
/// leniently (invalid UTF-8 is replaced); otherwise a single line is read
/// strictly, which fails on invalid UTF-8.
pub fn read_stream<R: Read>(
    inner: R,
    emit: &mut dyn FnMut(&str) -> io::Result<()>,
    flush: &mut dyn FnMut() -> io::Result<()>,
) -> io::Result<()> {
